  if (mob) {
    const d = dist(mob.x, mob.y, p.x, p.y);
    if (d > 0.5) {
      const ux = (p.x - mob.x) / d, uy = (p.y - mob.y) / d;
      let go = 0;
      for (let k = 2; k <= far; k += 2) { if (!canStand(m, p.x + ux * k, p.y + uy * k)) break; go = k; }
      if (go > 0) { p.x += ux * go; p.y += uy * go; p.fix = true; p.mvAt = S.now; }
    }
  }
