  rt.shots.push(shot);
  const ar = ["ar", shot.id, Math.round(shot.x), Math.round(shot.y), Math.round(ux * 1000), Math.round(uy * 1000), shot.spd, kind, p.eid];
  rt.ev.push(shot.home ? [...ar, shot.home] : ar);   // (a homing one names its monster)
