  const c = st.arm;
  const rt = S.maps[p.map];
  const now = S.now;
  if (st.wk === "hammer") {
    p.atkAt = now;
    p.combo = 0;
    p.swordBeat = null;
    newAct(p, false);
    startHammer(S, p, c);
    return;
  }
  const chained = now - p.atkAt < atkCd(p) + COMBO_MS;
  p.combo = chained ? (p.combo + 1) % 3 : 0;
