  if (sk.job && !skLearned(ch, sk)) return `[${JOBS[sk.job].name}] 직업 Lv.${sk.jobNeed}에 배웁니다`;
  if (!sk.job && ch.wm[sk.wk].lv < sk.need) return `[${WK_NAME[sk.wk]}] 숙련 ${sk.need}에 배웁니다`;
