/** What a skill costs right now. */
const skMp = (p, sk) => resoReady(p, sk) ? 0 : Math.max(0, Math.ceil(pfxNum(p, "mp", sk.mp * (100 - (skJobBonus(p, sk)?.mp || 0)) / 100)));
