const marksOf = (S, mob) => (mob.mkAt > S.now ? mob.mk | 0 : 0);
function addMarks(S, mob, n) {
  if (mob.dead) return;
  mob.mk = Math.min(MARK_MAX, marksOf(S, mob) + n);
  mob.mkAt = S.now + MARK_MS;
}
