  if (r.stone && addItem(ch, "stone", r.stone)) p.gain.push(["item", "stone", r.stone, 0]);
  if (r.rune) gainRune(S, p, r.gearQ >= 3 ? 2 : 1);
  if (r.gear) rewardGear(S, p, Math.floor(toTier(ch.lvl)), r.gearQ || 2);
  if (r.xp) gainXp(S, p, r.xp);
  p.dirty = true;
