const FAIR_SHOP = FAIR_SET.map((k, s) => [[FAIR_NOW[s], 20], [`hat_ssn_${k}`, 20], [`top_ssn_${k}`, 30], [`back_ssn_${k}`, 25], [`ws_ssn_${k}`, 25]]);

const fairFresh = () => ({ t: 0, d: 0, n: 0, pan: 0 });
