  ch.pity = pityFresh().map((_, i) => clamp(Array.isArray(ch.pity) && num(ch.pity[i]) ? Math.floor(ch.pity[i]) : 0, 0, PITY_CAP));
  const wk = isObj(ch.wk) ? ch.wk : {}, n = isObj(wk.n) ? wk.n : {}, b = isObj(wk.b) ? wk.b : {};
  const raw = weekRaw(ch), base = {};
