/** The world tier an instance is made for, from the highest player level going in (toTier; shown as 4·tier − 3). */
const dimLvOf = (ps) => clamp(Math.floor(toTier(Math.max(...ps.map((o) => o.ch.lvl)))), DIM.minTier, TIER_MAX - 1);
