  const [ox, oy] = tilePx(DIM_TOWN.ob), [kx, ky] = tilePx(DIM_TOWN.keeper);
  return dist(p.x, p.y, ox, oy) <= DIM.near || dist(p.x, p.y, kx, ky) <= DIM.near;
