    const id = type === "weapon" ? `w_${WK_ID[WK_ORDER[ri(box, 0, WK_ORDER.length - 1)]]}_${tier}` : `${GEAR[type].pre}_${tier}`;
    const g = rollGear(box, id, 3, Math.ceil((il + 3) / 4));   // (the power comes from the live pool, 51-prefix.js pfxPick)
