    tier, style: { floor: clamp(st.floor | 0, 0, HOUSE_FLOOR.length - 1), wall: clamp(st.wall | 0, 0, HOUSE_WALL.length - 1) }, furn: [],
    storage: (Array.isArray(o.storage) ? o.storage : []).map(fix).filter(Boolean),
