  if (stone && addItem(ch, "stone", stone)) p.gain.push(["item", "stone", stone, 0]);
  const tokens = gainWillowToken(p, 1);
  toast(p, `[${J.name}] ${"CBAS"[g - 1]} 등급! 보수 ${gold.toLocaleString()}G${hot ? " (특근!)" : ""}${tokens ? ` · 버드나무토큰 +${tokens}` : ""}`);
