  const ab = p.ab;
  if (!ab) return;
  if (a.t === "ab_leave" || (a.t === "ab_close" && ab.state !== "end")) { toast(p, "아르바이트를 그만두었습니다. 보수는 없습니다."); albaClear(S, p); return; }
  if (a.t === "ab_close") { albaClear(S, p); return; }
