      for (let i = 8; i > 0; i--) { const j = ri(box, 0, i), x = kinds[i]; kinds[i] = kinds[j]; kinds[j] = x; }
      const tb = Math.max(t, ...free);   // wait for the cans still busy: the bomb opens all nine within half a second
