    keep.forEach((y, i) => { for (let x = 0; x < W; x++) { const d = (PARCEL_H - keep.length + i) * W + x; nb[d] = g.b[y * W + x]; nf[d] = g.fr[y * W + x]; } });
    g.b = nb; g.fr = nf; g.rows += full.length; flags |= 1;
