const wallSpeed = (g) => (((40 + 4 * Math.min(g.lv, 4)) * (g.fs > 0 ? 7 : 10)) / 10) | 0;   // 1/16 px per sub-step
const wallEv = (g, type, x, y, v) => { g.ev.push([++g.seq, type, Math.round(x), Math.round(y), v | 0, g.n]); if (g.ev.length > 8) g.ev.shift(); };
