    // back from a try: step out of the ring first, then in again to retry
    if (dist(p.x, p.y, x, y) > STORY.r * T) { p.storyBack = 0; continue; }
    if (!p.storyBack && storyQuest(p.ch) === k) storyStart(S, p, rt);
