  const [x, y] = tilePx(stove[i]);
  if (dist(p.x, p.y, x, y) > COOP_T.station + 8) return "선택한 조리대 가까이에서 요리하세요.";
  if (c.pl[p.pid].hold.length) return "먼저 들고 있는 것을 내려놓으세요.";
