      const i = c.ents.findIndex((e) => Math.floor(e.x / T) === tx && Math.floor(e.y / T) === ty);
      if (i < 0) return "쓰레기가 있는 칸 위에서 주워 주세요.";
      if (q.hold.length >= COOP_APT.binCap) return "쓰레기통이 가득 찼어요! 비워주세요";
