    const pack = rt.mobs.filter((o) => o !== mob && !o.dead && !o.dive && !MOBS[o.k].still && !(o.rage > now) && dist(o.x, o.y, mob.x, mob.y) <= d.howl);
    if (!pack.length) return false;
