/** `here`: the players standing on this map when its turn began (in S.players order; each is checked again). */
function tickMob(S, m, rt, mob, dt, here) {
  const d = MOBS[mob.k];
  const now = S.now;
  if (mob.dead) {
    // (a cell's monster is gone for good: its cell sends another in its place, cellPass)
    if (!mob.temp && !mob.cellGone && now >= mob.respAt) { placeMob(S, m, mob); rt.ev.push(["r", mob.id]); }
    return;
  }
  if (mob.enchant === undefined) assignElementEnchant(S, mob);
  if (elementTick(S, rt, mob)) return;
  if (mob.dot) {
    // poison keeps biting once a second
    const dot = mob.dot;
    const moving = elementMoving(S, mob);
    if (now >= dot.until) mob.dot = null;
    else if (now >= dot.next) {
      dot.next = now + 1000;
      const o = S.players[dot.pid];
      if (o && o.map === m.id && dealTypedMob(S, rt, mob, o, dot.dmg * (moving ? 2 : 1), "bleed")) return;
    }
  }
  // a scripted field boss: its phases, the marked cast, the enrage (a challenge's boss: chalTick, 64-dim.js)
  if (d.script && !mob.chal) bsField(S, m, rt, mob);
  if (d.still) return;
  if (elementFrozen(S, mob)) return;
  // (a howl's rally: TRICKS.howl)
  const rage = mob.rage > now, atk = d.atk * ELITE[mob.el].atk * (rage ? TRICKS.howl.k : 1);
  // a charge already wound up goes off whatever is done to the charger in the meantime
  if (mob.act) {
    if (now >= mob.act.at) (mob.act.f ? landMove : dash)(S, m, rt, mob, atk);
    return;
  }
  // (a burrower whose trick was cut short, by a rift's reset say, comes back up)
  if (mob.dive === 2) mob.dive = 0;
  if (mob.stun > now) return;
  const swift = has(mob, "swift");
  const attackInterval = d.cd * elementAttackFactor(S, mob);
  const speed = d.spd * Math.min(mob.slow > now ? 0.5 : 1, elementMoveFactor(S, mob)) * (swift ? 1.35 : 1) * (rage ? 1.15 : 1);
  if (mob.dec) {
    // a rogue's puppet: walk up to it and strike it, which sets it off
    const dc = mob.dec;
    if (dc.gone || now >= dc.until) mob.dec = null;
    else {
      if (dist(mob.x, mob.y, dc.x, dc.y) <= d.range + 4) { if (now >= mob.atkAt) { mob.atkAt = now + attackInterval; rt.ev.push(["m", mob.id]); popDecoy(S, rt, dc); } }
      else stepMob(m, mob, dc.x, dc.y, speed, dt, d.fly, now);
      return;
    }
  }
  let tgt = mob.tgt ? S.players[mob.tgt] : null;
  const leash = Math.max(150, d.aggro * 2.4);
  if (tgt && (tgt.map !== m.id || tgt.dead || dist(mob.x, mob.y, mob.hx, mob.hy) > leash + 60 || dist(mob.x, mob.y, tgt.x, tgt.y) > leash)) {
    tgt = null; mob.tgt = null; mob.st = 2; mob.by = {};
  }
  const seesShade = d.boss || mob.el === 2;
  if (tgt && !seesShade && runeHidden(tgt, now)) return;
  if (!tgt && d.aggro > 0 && mob.st !== 2 && !(mob.daze > now)) {
    // fog: monsters see a little less far
    let bd = d.aggro * (rt.wx === WX.fog ? WX_FOG_AGGRO : 1);
    for (const p of here) {
      if (p.map !== m.id || p.dead || (p.foes || 0) >= AGGRO_CAP || p.hide > now || (!seesShade && runeHidden(p, now))) continue;
      const dd = dist(mob.x, mob.y, p.x, p.y);
      if (dd < bd) { bd = dd; tgt = p; }
    }
    if (tgt) { mob.tgt = tgt.pid; tgt.foes = (tgt.foes || 0) + 1; }
  }
  if (tgt) {
    const dd = dist(mob.x, mob.y, tgt.x, tgt.y);
    // a scripted boss (a challenge's, or MOBS[k].script) takes its turns from its script (56-boss-script.js)
    if (now >= mob.castAt && bsDef(mob)) { bsCast(S, rt, mob, tgt); return; }
    if (now >= mob.castAt) {
      const big = d.boss || mob.el === 2;
      // each kind has its own tricks: it tries them in turn and uses the first that suits the moment.
      // Bosses, guardians and field bosses alternate those with a blast on everyone in the fight.
      let used = false;
      mob.cn = (mob.cn || 0) + 1;
      if (!big || mob.cn % 2) {
        for (let i = 0; i < d.moves.length && !used; i++) {
          const k = d.moves[((mob.mv || 0) + i) % d.moves.length];
          if (special(S, m, rt, mob, tgt, dd, atk, k)) { used = true; mob.mv = ((mob.mv || 0) + i + 1) % d.moves.length; }
        }
      }
      if (!used && big) {
        mob.castAt = now + 6500;
        // one blast on every player in the fight: stand still and the whole party pays
        for (const o of here) {
          if (o.map !== m.id || o.dead || dist(mob.x, mob.y, o.x, o.y) > 220) continue;
          const r = d.boss ? 40 : 32;
          rt.tele.push({ x: o.x, y: o.y, r, at: now + 1300, dmg: atk * (d.boss ? 1.7 : 1.3), by: mob });
          rt.ev.push(["t", Math.round(o.x), Math.round(o.y), r, 1300]);
        }
      } else if (!used) mob.castAt = now + 800;        // nothing suited: look again shortly
      if (mob.act) return;
    }
    if (dd <= d.range) {
      if (now >= mob.atkAt) {
        mob.atkAt = now + attackInterval * (swift ? 0.74 : 1);
        mob.dir = tgt.x < mob.x ? 1 : 2;
        if (d.volley) { rt.ev.push(["m", mob.id]); volley(S, rt, mob, tgt, atk * 0.85, 3); }
        else {
          rt.ev.push(d.shot ? ["m", mob.id, Math.round(tgt.x), Math.round(tgt.y - 8)] : ["m", mob.id]);
          if (d.shot && tgt.wheel > now) rt.ev.push(["bl", tgt.eid]);
          else mobHit(S, rt, tgt, atk, mob);
        }
      }
    } else stepMob(m, mob, tgt.x, tgt.y, speed, dt, d.fly, now);
    return;
  }
  if (mob.st === 2) {
    const max = mobMax(mob);
    mob.hp = Math.min(max, mob.hp + max * 0.2 * dt * elementHealFactor(S, mob));
    if (stepMob(m, mob, mob.hx, mob.hy, speed * 1.4, dt, d.fly, now)) { mob.st = 0; mob.hp = max; }
    return;
  }
  if (now >= mob.mvAt) {
    mob.mvAt = now + 1500 + rnd(S) * 3500;
    mob.wx = mob.hx + (rnd(S) - 0.5) * 70;
    mob.wy = mob.hy + (rnd(S) - 0.5) * 70;
  }
  stepMob(m, mob, mob.wx, mob.wy, speed * 0.5, dt, d.fly, now);
}

// ───────────────────────────── active-area cells ─────────────────────────────
// docs/design/scale-and-rift.md B.4d: the monsters of a map live in its cells (m.cells, built
// with the map; rt.slots, one per monster a cell should hold). Cells near the living players
// wake and fill out of sight; far ones sleep and let their calm monsters go. Chests, bosses,
// guardians and event monsters are not in cells and never sleep.

/**
 * A tile in box r that is walkable and at least SPAWN_MIN_D tiles from every one of `pts` (tile
 * coordinates), or null. On a zoned map (33-maps-zones.js) only a tile of zone `z` will do.
 */
function placeAway(S, m, r, pts, z) {
  const [x0, y0, x1, y1] = r, d2 = SPAWN_MIN_D * SPAWN_MIN_D, zone = m.zone && z !== undefined ? m.zone : null;
  for (let i = 0; i < 24; i++) {
    const tx = ri(S, x0, x1), ty = ri(S, y0, y1);
    if (!m.reach[ty * m.w + tx] || (zone && zone[ty * m.w + tx] !== z)) continue;
    let ok = true;
    for (const [px, py] of pts) if ((tx + 0.5 - px) ** 2 + (ty + 0.5 - py) ** 2 < d2) { ok = false; break; }
    if (ok) return [tx, ty];
  }
  return null;
}
/**
 * A cell's crowd for `k` players near it: base × (0.75 + 0.25k), at most DENSITY_MAX; extra slots
 * come and (empty) go, but a wave's slots wait for their monster until their time (`exp`) is up.
 */
function crowdTo(rt, c, k, now) {
  const list = rt.slots[c], base = rt.base[c];
  const target = Math.round(base * Math.min(DENSITY_MAX, 0.75 + 0.25 * k));
  for (let i = list.length - 1; i >= base && list.length > target; i--) if (!list[i].mob && !(list[i].exp > now)) list.splice(i, 1);
  for (let i = list.length; i < target; i++) list.push({ q: list[i % base].q, c, mob: null, due: 0, extra: true });
}
/**
 * A cell falls asleep: its calm monsters leave (one still fighting stays until it calms, a later
 * pass), the ones killed there come back no sooner than CELL_RESPAWN_MS after its last kill, and
 * its extra slots go.
 */
function sleepCell(rt, c) {
  rt.cells[c] = 0;
  const list = rt.slots[c], since = rt.lastKill[c] + CELL_RESPAWN_MS;
  let gone = 0;
  for (const s of list) {
    const mob = s.mob;
    if (!mob) { s.due = Math.max(s.due, since); continue; }
    if (mob.tgt || mob.act) continue;
    mob.slot = null; mob.dead = true; mob.cellGone = true; s.mob = null; s.due = 0; gone++;
  }
  if (gone) for (let i = rt.mobs.length - 1; i >= 0; i--) if (rt.mobs[i].cellGone && rt.mobs[i].dead && !rt.mobs[i].slot) rt.mobs.splice(i, 1);
  for (let i = list.length - 1; i >= rt.base[c]; i--) if (!list[i].mob) list.splice(i, 1);
}
/**
 * Every CELL_PASS_MS on a map with players: wake the cells near the living, put to sleep the ones
 * nobody is near (the dead hold their ground too: dying never clears a crowd), send the waves, then
 * fill the empty slots of the awake cells near the living whose time has come, nearest cells first,
 * out of sight (of the dead too), never past WAKE_MAX_MOBS standing monsters.
 */
function cellPass(S, m, rt, pids) {
  const now = S.now;
  if (now < rt.cellAt || !m.cells) return;
  rt.cellAt = now + CELL_PASS_MS;
  const C = m.cells, cw = C.cw, ch = C.ch, nc = cw * ch;
  const folk = [], here = [];
  for (const pid of pids) { const p = S.players[pid]; if (p.map !== rt.id) continue; here.push(p); if (!p.dead) folk.push(p); }
  const cellX = (p) => clamp(Math.floor(p.x / T / CELL), 0, cw - 1), cellY = (p) => clamp(Math.floor(p.y / T / CELL), 0, ch - 1);
  // near: Chebyshev cells to the nearest living player; held: to the nearest player, dead or alive.
  // Only the cells within SLEEP_R of a player are looked at (the rest stay far).
  const near = new Int32Array(nc).fill(1 << 20), held = new Int32Array(nc).fill(1 << 20), crowd = new Uint8Array(nc);
  for (const p of here) {
    const px = cellX(p), py = cellY(p), live = !p.dead;
    for (let cy = Math.max(0, py - SLEEP_R); cy <= Math.min(ch - 1, py + SLEEP_R); cy++) for (let cx = Math.max(0, px - SLEEP_R); cx <= Math.min(cw - 1, px + SLEEP_R); cx++) {
      const d = Math.max(Math.abs(cx - px), Math.abs(cy - py)), c = cy * cw + cx;
      if (d < held[c]) held[c] = d;
      if (!live) continue;
      if (d < near[c]) near[c] = d;
      if (d <= WAKE_R) crowd[c]++;
    }
  }
  for (let c = 0; c < nc; c++) {
    if (!rt.base[c]) continue;
    if (held[c] > SLEEP_R) {
      if (rt.cells[c] || rt.slots[c].some((s) => s.mob)) sleepCell(rt, c);
      continue;
    }
    if (!rt.cells[c] && near[c] <= WAKE_R) rt.cells[c] = 1;
    if (rt.cells[c]) crowdTo(rt, c, crowd[c], now);
  }
  // waves: a hunter on the move finds more ahead of them
  for (const p of folk) {
    const w = p.wave;
    if (!w || w.map !== rt.id) { p.wave = { map: rt.id, at: now + WAVE_MS, x: p.x, y: p.y }; continue; }
    if (now < w.at) continue;
    const dx = (p.x - w.x) / T, dy = (p.y - w.y) / T, len = Math.hypot(dx, dy);
    w.at = now + WAVE_MS; w.x = p.x; w.y = p.y;
    if (len <= WAVE_MOVE) continue;
    const c = clamp(cellY(p) + Math.round((dy / len) * WAVE_AHEAD), 0, ch - 1) * cw + clamp(cellX(p) + Math.round((dx / len) * WAVE_AHEAD), 0, cw - 1);
    const base = rt.base[c], list = rt.slots[c];
    if (!rt.cells[c] || !base) continue;
    const add = Math.min(Math.ceil(base * WAVE_K), Math.floor(base * DENSITY_MAX) - list.length);
    for (let i = 0; i < add; i++) list.push({ q: list[i % base].q, c, mob: null, due: 0, extra: true, exp: now + WAVE_MS });
  }
  // fill
  let standing = 0;
  for (const mob of rt.mobs) if (!mob.dead && !mob.temp) standing++;
  if (standing >= WAKE_MAX_MOBS) return;
  const order = [];
  for (let c = 0; c < nc; c++) if (rt.cells[c] && rt.base[c] && near[c] <= SLEEP_R) order.push(c);
  order.sort((a, b) => near[a] - near[b] || a - b);
  const pts = here.map((p) => [p.x / T, p.y / T]);
  for (const c of order) for (const s of rt.slots[c]) {
    if (s.mob || now < s.due) continue;
    const at = placeAway(S, m, s.q.r, pts, s.q.zone);
    if (!at) continue;
    const mob = newMob(S, s.q.k, s.q.r, { elite: s.q.ep });
    mob.x = mob.hx = at[0] * T + 8; mob.y = mob.hy = at[1] * T + 10;
    readyMob(S, mob);
    mob.slot = s; s.mob = mob;
    rt.mobs.push(mob);
    if (++standing >= WAKE_MAX_MOBS) return;
  }
}

/** Advance the world to `now`. Maps nobody is standing in are frozen. */
export function tick(S, now) {
  const dt = clamp(now - (S.last || now), 0, 300) / 1000;
  S.last = now;
  S.now = now;
  worldEvent(S, now);
  fairWorld(S, now);   // 버드나무 장날 opening, said once in the chat (63-festival.js)
  skyTick(S, now);
  dimTick(S, now);
  storyTick(S, now);
  coopTick(S, now);     // 협동 아르바이트 shifts (68-coop.js)
  albaTick(S, now);     // 일일 아르바이트 shifts (66-alba.js)
  sxTick(S, now);       // trades and mini-games between players (69-social-play.js)
  homeTick(S, now);
  buddyTick(S, dt);
  const pids = Object.keys(S.players);
  for (const id of liveMapIds(S)) {
    const rt = S.maps[id];
    if (rt.n <= 0) continue;
    fbTick(S, rt, now);   // the field boss back at its spot, its quest's holder taken to the story fight (67-trophies.js)
    npcLifeTick(rt, now);
    const m = mapOfS(S, id);
    cellPass(S, m, rt, pids);
    // how many monsters are already after each player here
    const here = [];
    for (const pid of pids) if (S.players[pid].map === id) { S.players[pid].foes = 0; here.push(S.players[pid]); }
    for (const mob of rt.mobs) { const o = !mob.dead && mob.tgt ? S.players[mob.tgt] : null; if (o && o.map === id) o.foes++; }
    for (const mob of rt.mobs) tickMob(S, m, rt, mob, dt, here);
    shotTick(S, rt, dt);
    for (let i = rt.mobs.length - 1; i >= 0; i--) if ((rt.mobs[i].temp || rt.mobs[i].cellGone) && rt.mobs[i].dead) rt.mobs.splice(i, 1);
    for (let i = rt.zones.length - 1; i >= 0; i--) {
      const z = rt.zones[i];
      if (now < z.next) continue;
      const p = S.players[z.pid];
      if (!p || p.map !== id || (z.follow && p.dead)) { rt.zones.splice(i, 1); continue; }
      if (z.follow) { z.x = p.x; z.y = p.y; }
      z.next = now + z.every;
      rt.ev.push(["b", Math.round(z.x), Math.round(z.y), z.r, z.kind]);
      for (const o of mobsWithin(rt, z.x, z.y, z.r)) {
        if (z.slow) o.slow = now + 2500;
        if (z.knock) { const d = dist(z.x, z.y, o.x, o.y) || 1; knock(m, o, (o.x - z.x) / d, (o.y - z.y) / d, z.knock); }
        const before = o.hp;
        hurtMob(S, rt, o, p, z.mult, false, { px: z.px, elem: z.elem });
        if (!o.dead && o.hp < before && z.pfx === "hellfire") elementMark(S, o, "burn", z.every * 2);
      }
      if (--z.left <= 0) rt.zones.splice(i, 1);
    }
    skillProps(S, rt, m, now);
    for (let i = rt.tele.length - 1; i >= 0; i--) {
      const t = rt.tele[i];
      if (now < t.at) continue;
      rt.tele.splice(i, 1);
      rt.ev.push([t.ev || "b", Math.round(t.x), Math.round(t.y), t.r]);
      for (const pid of pids) {
        const p = S.players[pid];
        if (p.map !== id || p.dead || dist(p.x, p.y, t.x, t.y) > t.r) continue;
        mobHit(S, rt, p, t.dmg, t.by, t.how || (t.ev === "q" ? "shot" : "tele"));
      }
    }
    for (let i = rt.pools.length - 1; i >= 0; i--) {
      // a puddle bites whoever is standing in it, and leaves its mark on them
      const q = rt.pools[i];
      if (now >= q.until) { rt.pools.splice(i, 1); continue; }
      if (now < q.next) continue;
      q.next = now + 700;
      for (const pid of pids) {
        const p = S.players[pid];
        if (p.map !== id || p.dead || dist(p.x, p.y, q.x, q.y) > q.r) continue;
        // overlapping puddles do not add up: one bite at a time
        if (now < (p.poolAt || 0) + 600 || dodged(S, rt, p)) continue;
        p.poolAt = now;
        p.blame = { by: q.kind === 1 ? "불길" : q.kind === 2 ? "얼음 웅덩이" : "독 웅덩이", lv: 0, el: 0 };
        hurtPlayer(S, rt, p, q.dmg, null, q.kind === 1 ? "fire" : q.kind === 2 ? "cold" : "poison");
        if (!p.dead) afflict(S, p, q.kind === 1 ? "burn" : q.kind === 2 ? "slow" : "poison", q.atk);
      }
    }
    for (let i = rt.fires.length - 1; i >= 0; i--) if (rt.fires[i].until && now >= rt.fires[i].until) rt.fires.splice(i, 1);
    for (let i = rt.drops.length - 1; i >= 0; i--) {
      const dr = rt.drops[i];
      if (now >= dr.dieAt) { rt.drops.splice(i, 1); continue; }
      for (const pid of pids) {
        const p = S.players[pid];
        if (p.map !== id || p.dead) continue;
        if (dr.own !== pid && now < dr.freeAt) continue;
        if (dist(p.x, p.y, dr.x, dr.y) > 15) continue;
        if (!pickUp(S, p, dr)) continue;
        rt.drops.splice(i, 1);
        break;
      }
    }
    // a pet runs for its owner's own drops within its reach, one at a time, minding the
    // loot filter and the room in the bag (메이플 펫의 줍기)
    if (rt.drops.length) for (const pid of pids) {
      const p = S.players[pid];
      if (p.map !== id || p.dead || !p.ch.pet || now < (p.petAt || 0)) continue;
      const reach = ITEMS[p.ch.pet].radius;
      let best = -1, bd = reach;
      for (let i = 0; i < rt.drops.length; i++) {
        const dr = rt.drops[i];
        if (dr.own !== pid || !wanted(p.ch, dr) || !fits(p.ch, dr)) continue;
        const d = dist(p.x, p.y, dr.x, dr.y);
        if (d <= bd) { bd = d; best = i; }
      }
      if (best < 0) continue;
      p.petAt = now + pfxNum(p, "pet", PET_MS);
      const dr = rt.drops[best];
      if (pickUp(S, p, dr)) { rt.drops.splice(best, 1); rt.ev.push(["pk", p.eid, Math.round(dr.x), Math.round(dr.y)]); }
    }
  }
  for (const pid of pids) {
    const p = S.players[pid];
    if (p.pinv && now - p.pinv.at > 30000) p.pinv = null;
    if (p.ginv && now - p.ginv.at > 30000) p.ginv = null;
    if (p.fish) {
      // a bite, then a short moment to reel it in
      const rt = S.maps[p.map];
      if (!p.fish.bite && now >= p.fish.at) { p.fish.bite = now; rt.ev.push(["f", p.eid, 2]); }
      else if ((p.fish.bite && !p.fish.hook && now > p.fish.bite + 1800) || (p.fish.hook && now > p.fish.hook + 25000)) { p.fish = null; rt.ev.push(["f", p.eid, 0]); toast(p, "물고기가 달아났습니다."); }
    }
    if (!p.dead) {
      // fire and poison bite once a second until they run out
      for (const key of ["burn", "poison"]) {
        const s = p[key];
        if (!s) continue;
        if (now >= s.until) { p[key] = null; continue; }
        if (now >= s.next) {
          s.next = now + 1000;
          const type = key === "burn" ? "fire" : "poison";
          wound(S, S.maps[p.map], p, s.dmg * elementResist(S, p, type), type);
          if (p.dead) break;
        }
      }
      if (!p.dead) elementTick(S, S.maps[p.map], p);
    }
    if (p.recall && now >= p.recall.at && !p.dead) finishRecall(S, p);
    // life skills: gathering channels, parcels, node cooldowns, the 알바 board's day (58-life.js)
    lifeTick(S, p, now);
    windTouch(S, p, now);
    if (p.rallyAt && now >= p.rallyAt) { p.rallyAt = 0; p.dirty = true; }
    if (!p.dead && !elementFrozen(S, p)) weaponTick(S, p, now);
    if (p.dead || now - p.regenAt < 1000) continue;
    p.regenAt = now;
    ensureDaily(S, p);
    if (!S.dims[p.map]?.story?.airship) explore(S, p);
    const st = stats(p);
    const calm = now - p.hitAt > 5000;
    // a campfire is a place to catch your breath; sitting by it is better still
    const fire = calm ? fireNear(S.maps[p.map], p) : null;
    const rest = fire ? pfxNum(p, "rest", p.sit ? 0.12 : 0.06) : mapOfS(p.S, p.map).safe ? 0.08 : 0.02;
    // a fire's warmth carries on after you stand up, as long as you keep out of a fight
    const wr = calm ? warmRegen(p, now) : 0;
    if (calm && p.hp < st.mhp) p.hp = Math.min(st.mhp, p.hp + (st.mhp * (rest + wr) + 1) * elementHealFactor(S, p));
    if (p.mp < st.mmp) p.mp = Math.min(st.mmp, p.mp + st.mmp * ((fire ? rest : 0.03) + wr + st.mpReg) + 1);
    if (fire && p.sit) warmTick(S, p, fire, now);
    else p.warmT = 0;
    pfxTick(S, S.maps[p.map], p, st, now, calm);   // the prefix powers that work once a second (regen, cleanse, resting)
  }
  return S;
}

/** Call once every player's view for this tick has been taken. */
export function endTick(S) {
  for (const id of Object.keys(S.maps)) {
    const rt = S.maps[id];
    rt.ev.length = 0;
    rt.who = false;
    if (rt.npcRows?.length) rt.npcRows = null;
  }
  S.chat.length = 0;
}

export function isGameOver() {
  return { over: false };
}

/** Today's tasks as the player sees them: what, how far, what it pays, and when they renew. */
function dailyView(p) {
  const ch = p.ch, dl = ch.daily;
  if (!dl) return null;
  return {
    day: dl.day, reset: Math.max(0, nextReset(p.S.now) - p.S.now), bonus: dl.bonus, bonusReward: dailyBonus(ch),
    tasks: dl.tasks.map((t, i) => ({ kind: t.kind, k: t.k, n: t.n, need: t.need, done: t.n >= t.need, claimed: dl.claimed[i], text: dailyText(t), reward: dailyReward(ch, t) })),
  };
}
function selfPayload(p) {
  const ch = p.ch;
  const st = stats(p);
  const { runeSets, runeCounts } = deriveStats(p);
  const now = p.S.now;
  const enh = {};
  for (const k of SLOTS) enh[k] = ch.eq[k] && !isJewel(ch.eq[k].id) ? enhCost(ch.eq[k]) : null;
  return {
    // jobs and stats: the job, the level (1 + points), unspent and spent experience, the six stats and
    // what the next point in each costs (0 at a cap), resets left, the starter pick taken, mastery
    // [lv, xp, need] per kind (WK_ORDER), the kinds in hand and on the back
    name: ch.name, job: ch.job, lvl: ch.lvl, xp: ch.xp, xpt: ch.xpt, st: ch.st, nx: nextCosts(ch), rs: ch.rs, sw: ch.sw, respecCost: statResetCost(ch),
    buddy: buddySelf(p),
    wm: WK_ORDER.map((k) => [ch.wm[k].lv, Math.floor(ch.wm[k].xp),ch.wm[k].lv >= WM_MAX ? 0 : wmNeed(ch.wm[k].lv)]),
    jp: ch.jp ? [ch.jp.lv, ch.jp.xp, ch.jp.lv >= JOB_PROGRESS.cap ? 0 : jobNeed(ch.jp.lv)] : null,
    wk2: ch.eq.weapon2 ? ITEMS[ch.eq.weapon2.id].wk : "",
    // 직업 자유 (47-job-freedom.js): [[job, lv, xp]] every job walked; the loadout [actives, passives, off-job passive, set 1/0, off slot open 1/0]
    jobs: Object.keys(ch.jobs).map((j) => [j, ch.jobs[j].lv, ch.jobs[j].xp]),
    // skill enhancement { [id]: +n } (48-skill-enh.js)
    ske: ch.ske,
    lo: (() => { const lo = loOf(ch); return [lo.a, lo.p, lo.x, ch.lo[ch.job] ? 1 : 0, loOpen(ch) ? 1 : 0, lo.y, loPower(ch)]; })(),
    gold: ch.gold,
    mhp: st.mhp, mmp: st.mmp, atk: st.atk, def: st.def, crit: r1(st.crit), critd: Math.round(st.critd * 100), ls: st.ls, xpb: st.xp, mf: Math.round(st.mf), spd: st.spd0,
    goldb: st.gold, lg: Object.keys(st.lg), wk: weaponKind(ch), acd: atkCd(p), range: atkRange(p),
    runeSets, runeCounts,
    element: st.element,
    // derived: attack type (0 physical, 1 magic), evasion %, attack speed %, cooldown cut %, status resist %, poise %,
    // knockback resist %, elemental burst %, item find from luck %, graze chance on a monster of your own tier %
    dv: [st.mag, r1(st.eva), r1(st.aspd * 100), r1(st.cdr * 100), r1(st.res * 100), r1(st.poise * 100), r1(st.kbr * 100), r1(st.burst * 100),
      r1(Math.min(SFX.mf[1], SFX.mf[0] * eff(ch.st.luk))), clamp(SFX.graze[0] - (ch.eq.weapon ? ch.wm[weaponKind(ch)].lv : 0), 0, SFX.graze[3])],
    // the weapon passive's gauge (57 crView), and every skill learned: [id, MP now, cooldown left ms, usable in hand 1/0]
    cr: crView(p, now), sk: skWire(p, now),
    inv: charmBag(ch.inv), eq: ch.eq, q: ch.q, kills: ch.kills || 0, enh, qs: ch.qs,
    bq: ch.bq, bn: ch.bn, mk: ch.mk, streak: [p.streak, Math.max(0, STREAK_MS - (now - p.streakAt))],
    // attack up, speed up, warmth, food — then what monsters leave on you: slowed, burning, poisoned —
    // then the scrolls being read: attack, defence, experience
    buffs: [Math.max(0, p.atkBuff - now), Math.max(0, p.spdBuff - now), Math.max(0, p.warm - now), p.food ? Math.max(0, p.food.until - now) : 0,
      Math.max(0, (p.slowed || 0) - now), p.burn ? Math.max(0, p.burn.until - now) : 0, p.poison ? Math.max(0, p.poison.until - now) : 0,
      Math.max(0, ch.scr.atk - now), Math.max(0, ch.scr.def - now), Math.max(0, ch.scr.xp - now),
      // then 질주의 바람 (a wind shrine's push)
      Math.max(0, (p.wind || 0) - now),
      // then 안락한 휴식 (a bed or a hearth at home, 64-housing.js)
      Math.max(0, ch.house.cozy - now)],
    wh: ch.wh, pet: ch.pet, opt: ch.opt, cos: ch.cos, cosDye: ch.cosDye, sq: sqView(ch, now), keep: Object.keys(ch.keep),
    dead: p.dead ? { loss: deathLoss(ch, p), feather: countItem(ch, "feather"), by: p.blame ? p.blame.by : null, lv: p.blame ? p.blame.lv : 0, el: p.blame ? p.blame.el : 0 } : null,
    warm: p.warmPct, food: p.food ? p.food.id : null, guild: ch.guild, gm: ch.gm, fishN: ch.fish,
    // waypoint stones woken: { mapId: bitmask } (bit 0 = the map's first stone)
    wp: ch.wp, seen: ch.seen, ach: ch.ach, pts: achPoints(ch), title: ch.title, col: REGIONS.filter((id) => regionDone(ch, id)), cnt: ch.cnt,
    daily: dailyView(p), tut: { i: ch.tut.i, n: ch.tut.n }, evt: evtView(p.S, p), recall: p.recall ? Math.max(0, p.recall.at - now) : 0,
    gmates: ch.guild ? Object.keys(p.S.players).map((id) => p.S.players[id]).filter((o) => o.ch.guild === ch.guild).map((o) => [o.eid, o.ch.name, o.ch.job, o.ch.lvl, mapOfS(o.S, o.map).name, o.ch.gm]) : [],
    // the bag's size (46-bag.js) and the house (64-housing.js homeSelf)
    bagCap: bagCap(ch), house: homeSelf(p),
    // 균열 단수 and the weekly boss flags (64-dim.js dimSelf)
    dimr: dimSelf(p),
    // charms (66-charms.js): the board, what waits at 주아나, her quest; a sealed charm's seal never leaves the server
    charms: charmSelf(p),
    // boss trophies held (67-trophies.js): field-boss kinds, in the order won
    tro: p.ch.tro,
    // life skills (58-life.js): [lv, xp, need] per skill in LIFE order; L2: the 알바 board, trust, the 재료 주머니
    life: lifeView(ch), jb: jbView(p), rep: repView(ch), pouch: ch.pouch, fbook: ch.fbook,
    // 버드나무 장날 (63-festival.js): [purse, earned today, my best pan, the day's best, its cook]
    fair: fairSelf(p),
    // the block list, the enhancement pity gauge, the weekly book (63-social-weekly.js)
    ...socialSelf(p),
    // 협동 아르바이트 paid today (68-coop.js)
    coop: coopSelf(p),
    // 일일 아르바이트 paid today, best scores, pay slots left (66-alba.js)
    alba: albaSelf(p),
    // the slots whose 고유 효과 does not count (the same power on a better or earlier piece): the tooltip greys it (51-prefix.js)
    lgOff: st.lgOff,
  };
}

function elementView(S, out, eid, entity) {
  if (entity.dead) return;
  const rows = elementStatusRows(S, entity);
  if (rows.length) (out.ail || (out.ail = [])).push([eid, rows]);
}

/**
 * One player's slice of the world for this tick: only their map, only what is
 * near them, and their own sheet only when it changed.
 */
export function viewFor(S, pid) {
  const p = S.players[pid];
  if (!p) return null;
  const rt = S.maps[p.map];
  const near = (o) => Math.abs(o.x - p.x) < VIEW_X && Math.abs(o.y - p.y) < VIEW_Y;
  // The browser adopts these coordinates on corrections and arrival. Keep its feet in the
  // same integer collision cells as the server's, even when a valid position hugs a wall.
  const selfPos = p.fix || p.sendMap ? Math.floor : Math.round;
  const out = {
    type: "snap",
    me: [selfPos(p.x), selfPos(p.y), Math.round(p.hp), Math.round(p.mp), p.dead ? 1 : 0, p.fix ? 1 : 0, p.dir, p.sit ? 1 : 0, flagsOf(p, S.now), crValue(p, S.now), p.aim | 0, dashLeft(S, p)],
    P: [], M: [], D: [], F: [],
  };
  // me[12] / a P row's [9]: the carry code (58-life.js carryOf), only while something is held
  const held = carryOf(p);
  if (held) out.me.push(held);
  albaView(S, p, out);   // the 일일 아르바이트 shift in hand (66-alba.js)
  elementView(S, out, p.eid, p);
  const elementSpeed = elementFrozen(S, p) ? 0 : elementMoveFactor(S, p);
  if (elementSpeed !== 1) out.elspd = elementSpeed;
  // a prefix power speeding the walk for a moment (질주·추격 …): only while it does, so the client's own steps keep up with the rules'
  if (deriveStats(p).pfx.stat.length) { const ps = stats(p).pspd; if (ps) out.pspd = Math.round(ps * 1000) / 1000; }
  for (const oid of Object.keys(S.players)) {
    const o = S.players[oid];
    if (o === p || o.map !== p.map || !near(o)) continue;
    const row = [o.eid, Math.round(o.x), Math.round(o.y), o.dir, o.dead ? 1 : 0, Math.round(o.hp), stats(o).mhp, o.sit ? 1 : 0, flagsOf(o, S.now)], c = carryOf(o);
    if (c) row.push(c);
    out.P.push(row);
    elementView(S, out, o.eid, o);
  }
  for (const b of Object.values(S.buddies)) {
    if (b.map === p.map && near(b)) out.P.push([b.eid, Math.round(b.x), Math.round(b.y), b.dir, 0, 1, 1, 0, 0]);
  }
  buddyView(p, out);
  for (const mob of rt.mobs) {
    // a field boss (or the rift invasion's lord) is shown on the radar wherever it stands on the map
    if (mob.temp && mob.el === 2 && !mob.dim && !mob.dead) (out.fb || (out.fb = [])).push([Math.round(mob.x), Math.round(mob.y)]);
    // (a burrowing monster is underground: not shown until it comes up, 80-simulation.js special)
    if (mob.dead || !near(mob) || (mob.dive && !bsDef(mob))) continue;
    // then, only when there is one: the dagger's marks on it, and 1 when it bears a book's brand
    const mk = marksOf(S, mob), br = mob.brand > S.now ? 1 : 0;
    const row = [mob.id, mob.k, Math.round(mob.x), Math.round(mob.y), mob.dir, Math.ceil(mob.hp), mob.el, mob.tr || []];
    // a scripted boss (56-boss-script.js) always carries both, then its phase, 0 · 1 marked cast · 2 dived out of reach,
    // and while it casts the stagger gauge still to break (%)
    if (bsDef(mob)) row.push(mk || 0, br, mob.bs ? mob.bs.ph : 1, mob.dive ? 2 : mob.cast ? 1 : 0, mob.cast ? Math.ceil(100 * (1 - mob.cast.got / mob.cast.need)) : 0);
    else {
      if (mk || br) row.push(mk);
      if (br) row.push(1);
    }
    out.M.push(row);
    if (mob.enchant) (out.enc || (out.enc = {}))[mob.id] = DAMAGE_TYPES.indexOf(mob.enchant);
    elementView(S, out, mob.id, mob);
    // a rift's toughness (64-dim.js hk: party size, level, tier) — only where it isn't 1, so the bar can show the real HP
    if (mob.hk && mob.hk !== 1) (out.HK || (out.HK = {}))[mob.id] = Math.round(mob.hk * 1000) / 1000;
  }
  for (const dr of rt.drops) {
    if (near(dr) && (dr.own === pid || S.now >= dr.freeAt)) out.D.push([dr.id, dr.it, Math.round(dr.x), Math.round(dr.y), dr.q]);
  }
  for (const f of rt.fires) if (near(f)) out.F.push([f.id, f.x, f.y]);
  if (rt.ev.length) out.ev = rt.ev;
  // guild chat reaches only the guild
  // (and a whisper only its reader, and nobody a name they blocked: 63-social-weekly.js chatFor)
  if (S.chat.length) { const chat = chatFor(S, p, pid); if (chat.length) out.chat = chat; }
  if (p.sendMap) out.map = mapPayload(mapOfS(S, p.map));
  // the sky: [weather (-1 under a roof), server clock in seconds, season 0–3, 장날 open 0/1 (63-festival.js)], when
  // the weather turns or the market opens or closes, on arrival, and once a minute to keep everyone's hour in step
  const wx = rt.wx ?? weatherAt(p.map, S.now), fo = fairOpen(S.now) ? 1 : 0;
  if (p.sendMap || wx !== p.wx || fo !== p.fairDn || S.now - (p.dnAt || 0) >= 60000) { out.dn = [wx, Math.floor(S.now / 1000), seasonOf(S.now), fo]; p.wx = wx; p.fairDn = fo; p.dnAt = S.now; }
  if (p.sendMap || rt.who) {
    out.who = [];
    for (const oid of Object.keys(S.players)) {
      const o = S.players[oid];
      if (o.map !== p.map) continue;
      // what everyone can see of this player: look, party, and the weapon in hand
      // (its tier, rarity, enhancement and kind)
      const ar = o.ch.eq.armor, wp = o.ch.eq.weapon;
      out.who.push([o.eid, o.ch.name, o.ch.job, o.ch.lvl, o.ch.look, ar ? ITEMS[ar.id].tier : 0, wp ? ITEMS[wp.id].tier : 0, o.party,
        wp ? wp.q : 0, wp ? wp.enh : 0, o.ch.pet || 0, weaponKind(o.ch), o.ch.guild, titleOf(o.ch),
        // the outfit (cosmetic codes, slot order) and the weapon's legendary power, for its look
        cosWire(o.ch), wp ? wp.lg || (ITEMS[wp.id].uniq ? wp.id : "") : "",   // a signature weapon can have its own look
        // a hybrid's second weapon, on the back
        o.ch.eq.weapon2 ? ITEMS[o.ch.eq.weapon2.id].wk : ""]);
    }
    for (const b of Object.values(S.buddies)) {
      if (b.map !== p.map) continue;
      const { name, job, lvl, look, wk } = b.ch;
      out.who.push([b.eid, name, job, lvl, look, 0, 1, 0, 0, 0, 0, wk, "", "", [], "", "", 1]);
    }
  }
  if (p.party) {
    // … then where each stands (pixels, for the radar and the map window) and the id of their map
    out.party = members(S, p).map((o) => [o.eid, o.ch.name, o.ch.job, o.ch.lvl, Math.round(o.hp), stats(o).mhp, o.map === p.map ? "" : mapOfS(o.S, o.map).name, Math.round(o.x), Math.round(o.y), o.map]);
  }
  if (p.pinv) {
    const from = S.players[p.pinv.from];
    if (from) out.pinv = from.ch.name;
  }
  if (p.ginv) {
    const from = S.players[p.ginv.from];
    if (from) out.ginv = [from.ch.name, p.ginv.g];
  }
  if (p.dirty) out.self = selfPayload(p);
  // a 장날 merchant's list, once when asked for (and after a purchase): fm (64-fair-market.js)
  if (p.fmSend) { const fm = fairMktWire(S, p, p.fmSend); if (fm) out.fm = fm; p.fmSend = null; }
  if (p.gain.length) out.gain = p.gain;
  dimView(S, p, out);
  coopView(S, p, out);   // 협동 아르바이트: cj, C, cr (68-coop.js)
  sxView(S, p, out);     // requests, trade window, mini-game: sx when it changes (69-social-play.js)
  // this map's gathering nodes the player has spent, when that changes (58-life.js)
  lifeSnap(S, p, out);
  npcLifeSnap(S, p, out);
  if (p.toast.length) out.toast = p.toast;
  p.sendMap = false; p.fix = false; p.dirty = false; p.gain = []; p.toast = [];
  return out;
}

/** Static tables the browser needs to draw windows and tooltips. Sent once. */
/**
 * The generated world as the generators left it, for the map tests: every map with
 * its spawns, set pieces and region count, plus the camps and waypoint stones (this
 * builds every map). With `fresh`, everything (or only `ids`) is generated again from
 * the seeds, apart from the kept maps (for checking determinism and build time).
 */
export function atlas(fresh = false, ids = null) {
  if (!fresh) return { maps: allMaps(), fires: FIRES, waypoints: WP };
  const maps = {};
  for (const id of ids || Object.keys(MAP_META)) {
    maps[id] = finishMap(baseMap(id));
    for (const pt of maps[id].portals) arrivalOf(null, pt);
  }
  return { maps, fires: FIRES, waypoints: WP };
}
/** The registry, for the tests: which maps are built so far, and what is known of every map without building it. */
export function mapStats() {
  return { built: Object.keys(MAP_CACHE), meta: MAP_META };
}

// Fixed positions for the main world map at 1×. Editor maps fall back to layout by route.
const WORLD_MAP_POS = {
  willow: [170, 233], blossom_trail: [152, 148], sunset_beach: [118, 316], town: [327, 205], meadow: [348, 93], forest: [548, 124], crypt: [723, 133],
  city: [367, 334], sewer: [552, 320], cave: [710, 302], abyss: [928, 335], maple: [824, 229],
  jungle: [203, 417], coast: [370, 528], oasis: [622, 470], dunesea: [838, 516], frostkeep: [915, 91],
  airship: [622, 389], mesa: [764, 386], inklake: [850, 300],
};
const WORLD_MAP_ART = { willow: "willow", blossom_trail: "blossom_trail", sunset_beach: "coast", frostkeep: "frostkeep", dunesea: "dunesea", airship: "airship" };

function worldMapDefs() {
  // Only custom labels need coordinates to disambiguate the destination. Keep generated terrain lazy.
  const doors = {};
  for (const link of DATA.links) {
    if (typeof link.label !== "string" || !link.label) continue;
    const from = realId(link.map), to = realId(link.to);
    if (!from || !to || !xyOk(MAP_META[from], link.x, link.y) || !xyOk(MAP_META[to], link.tx, link.ty)) continue;
    (doors[from] ??= []).push([link.x, link.y, to]);
  }
  return Object.entries(MAP_META).map(([id, meta]) => {
    const { name, band, kinds, theme, safe, w, h, wpn, minLv } = meta;
    const kind = theme === "interior" ? "in" : safe ? "town" : (minLv || ["crypt", "sewer", "cave", "abyss"].includes(theme)) ? "dun" : "field";
    const bosses = [...new Set([FIELD_BOSS[id], ...kinds.filter((mob) => MOBS[mob].boss)].filter(Boolean))];
    return { id, name, band: band && band.map(shownLv), mobs: kinds.slice(), theme, safe, w, h, wpn, to: ROUTES[id],
      kind, gateLabel: doorName(meta), pos: WORLD_MAP_POS[id]?.slice() || null, bosses, ...(Object.hasOwn(WORLD_MAP_ART, id) ? { art: WORLD_MAP_ART[id] } : {}), ...(minLv ? { minLv } : {}), ...(doors[id] ? { doors: doors[id] } : {}),
      ...(id === AIRSHIP_MAP ? { unlockQuest: AIRSHIP_QUEST } : {}) };
  });
}

/** One side quest for the client: who gives it and takes it back, where its goal is, what to call it (sidequests.js, track.js). */
function sideDef(q) {
  const g = q.goal, r = g.type === "make" ? sqRecipe(g.item) : null, to = sqTurnIn(q);
  return { ...q, giverName: npcName(q.giver), giverMap: MAP_META[NPC_MAP[q.giver]].name, giverMapId: NPC_MAP[q.giver],
    turnIn: to, turnInName: npcName(to), turnInMap: MAP_META[NPC_MAP[to]].name,
    targetMap: q.id === AIRSHIP_QUEST ? AIRSHIP_MAP : g.type === "talk" || g.type === "deliver" ? NPC_MAP[g.npc] : g.type === "visit" || g.map ? g.map || null : null,
    // make: where the recipe is made ("fire" = any campfire, else the station's NPC)
    ...(r ? { station: r.at === "fire" ? "fire" : SQ_STATION[r.at] || null, ...(SQ_STATION[r.at] ? { stationName: npcName(SQ_STATION[r.at]) } : {}) } : {}),
    target: g.type === "kill" ? MOBS[g.mob].name : g.type === "collect" || g.type === "make" || g.type === "deliver" ? ITEMS[g.item].name : g.type === "talk" ? npcName(g.npc)
      : g.type === "elite" || g.type === "fb" ? g.named || `${g.map ? MAP_META[g.map].name + " " : ""}${g.type === "fb" ? "우두머리" : g.mob ? `정예 ${MOBS[g.mob].name}` : "정예 몬스터"}`
        : g.type === "choice" ? npcName(q.giver) : MAP_META[g.map].name };
}
export function defs() {
  const mobs = {};
  for (const k of Object.keys(MOBS)) {
    const d = MOBS[k];
    const { type, res, holyWeak } = monsterElement(k);
    // levels as players see them (4·tier − 3); `tier` the world's own
    mobs[k] = { name: d.name, lore: d.lore || MOB_LORE[k] || "", sp: d.sp, tint: d.tint || null, lv: shownLv(d.lv), tier: d.lv, hp: d.hp, boss: d.boss ? 1 : 0, chest: d.chest ? 1 : 0, xp: d.xp, fly: d.fly ? 1 : 0, aggro: d.aggro || 0 };
    Object.assign(mobs[k], { element: type, resist: res, holyWeak });
    if (d.epithet) mobs[k].epithet = d.epithet;
    if (d.bonusOptional) mobs[k].optional = 1;
    if (d.questOnly) mobs[k].questOnly = 1;
  }
  const affix = {};
  for (const [k, label, prefix] of AFFIX) affix[k] = [label, prefix];
  // jobs and stats: the jobs (with each weapon's scaling as coefficients), the stats, the scaling grades,
  // the base cost of each of the 200 levels' point (pointCost at a stat ≤ 30) and the stat surcharge
  // [STAT_K, STAT_K0] — the one rule the client mirrors for its cost preview; mastery need per level.
  // jobs[id].wm: the mastery each of its weapons needs (single JOB_WM, hybrid HYB_WM); .sig its signature skill
  const jobs = {};
  for (const id of Object.keys(JOBS)) {
    const j = JOBS[id];
    jobs[id] = { name: j.name, kind: j.kind, wk: j.wk.slice(), cost: j.cost, scale: j.kind === "hybrid" ? { ...j.scale } : j.kind === "single" ? scaleOf({ job: id }, j.wk[0]) : {}, wm: j.kind === "none" ? 0 : jobWmOf(id), sig: JOB_SKILL[id] || "" };
  }
  return {
    worldName: "루넬샤대륙",
    items: ITEMS, mobs, skills: SKILL, skillOrder: SKILL_ORDER, skGrow: SK_GROW, jobPal: JOB_PAL, skillJob: SKILL_JOB, shop: SHOP, quests: QUESTS, enh: ENH_RATE, enhPct: ENH_PCT, enhCrit: ENH_CRIT, enhUc: ENH_UNCURSE, uncurseFee: UNCURSE_FEE, inv: INV_BASE, invMax: INV_MAX, bag: { step: BAG_STEP, cost: BAG_COST }, house: homeDefs(), maxLv: MAXLV,
    jobs, jobSkillRanks: JOB_SKILL_RANKS, stats: STATS, scale: SCALE, grade: GRADE, lvc: Array.from({ length: MAXLV }, (_, i) => pointCost(i + 1, 0)), statK: [STAT_K, STAT_K0],
    wmNeed: Array.from({ length: WM_MAX }, (_, i) => wmNeed(i + 1)), wkOrder: WK_ORDER, wkName: WK_NAME, jobWm: JOB_WM, hybWm: HYB_WM, wswMs: WSW_MS,
    // 직업 자유: loadout sizes, the reset scrolls and gold [base, per level], the off-slot quest
    ske: { rate: SKE_RATE, pct: SKE_PCT, max: SKE_MAX, item: SKE_ITEM },
    jf: { lo: [LO_MAX.a, LO_MAX.p], borrow: LO_BORROW, scroll: JF_SCROLL, cost: JF_COST, quest: JF_QUEST, respecItem: RESPEC_ITEM },
    // J3: the stat panel's exact cost mirror — tierXp of each level and LV_DIV, so the client rounds once as pointCost does
    // (lvc is already rounded, so lvc × surcharge can miss by one)
    lvt: Array.from({ length: MAXLV }, (_, i) => tierXp(toTier(i + 1))), lvDiv: LV_DIV,
    affix, runes: RUNES, runeScale: RUNE_SCALE, runeSets: RUNE_SETS, runeSetMax: RUNE_SET_MAX, runeRarity: RUNE_RARITY, sockCaps: SOCK_CAPS, sockCost: SOCK_COST, sockItem: SOCK_ITEM,
    elements: { types: DAMAGE_TYPES, info: ELEMENTS, status: ELEMENT_STATUS, basic: Object.fromEntries(WK_ORDER.map((wk) => [wk, skillDamageType("", wk)])) },
    elementPrefixes: ELEMENT_PREFIX_AFFIX,
    rarity: RARITY, eliteHp: ELITE.map((e) => e.hp), partyMax: PARTY_MAX,
    fieldParty: { tiles: FIELD_PARTY_RANGE / T, share: PARTY_SHARE },
    slots: SLOTS, wkinds: WKIND, legend: LEGEND, mastery: MASTERY, bounty: BOUNTY_N, fbResp: FB_RESP,
    traits: TRAITS, slow: SLOW, aim: [AIM_N, AIM_CONE], dash: [DASH.px, DASH.ms, DASH.cd, DASH.inv], mech: { marks: MARK_MAX, tip: SKILL.tip.at, tipMult: SKILL.tip.mult, react: REACT, elem: ELEM, weaveMs: WEAVE_MS }, whSlots: WH, filters: ["모두", "마법 이상", "희귀 이상"], petMs: PET_MS,
    // n: how many stones the map has (woken as "<id>" for the first, "<id>#<i>" for the others), names: what each is called
    waypoints: Object.keys(MAP_META).filter(hasWp).map((id) => ({ id, name: MAP_META[id].name, band: MAP_META[id].band && MAP_META[id].band.map(shownLv), n: MAP_META[id].wpn || 1, names: stoneNames(id), minLv: MAP_META[id].minLv || undefined })),
    // the wardrobe: id → { n wire code, slot, name, q rarity, src, price, ach, desc }; `cosN[n]` the id of a code
    cos: COSMETICS, cosSlots: COS_SLOTS, cosSlotName: COS_SLOT_NAME, cosN: COS_BY_N, cosSets: COS_SETS,
    // 염색 (P9): the dye items in self.cosDye order (1 = cosDyes[0]); a worn code ≥ cosDyeK carries a dye; keepsake → outfit piece ("" not yet)
    cosDyes: COS_DYES, cosDyeK: COS_DYE_K, keepSew: KEEP_SEW,
    achievements: ACH.map(({ id, cat, name, desc, pts, title, bonus }) => ({ id, cat, name, desc, pts, title, bonus })),
    collection: Object.fromEntries(REGIONS.map((id) => [id, { mobs: COL_MOBS[id], bonus: REGION_BONUS[id] }])), colNeed: MASTERY[0],
    event: { every: EVT.every, warn: EVT.warn, len: EVT.len, waves: EVT.waves, boss: EVT.boss, maps: EVT_MAPS },
    daily: { resetKST: 6, text: DAILY_TEXT }, social: socialDefs(), tutorial: TUT.map(({ id, title, hint, need }) => ({ id, title, hint, need: need || 1 })), recallMs: RECALL_MS,
    // side quests from the world map editor, with who gives them and where they stand
    questTurnIn: { npc: "elder", map: NPC_MAP.elder },
    // every NPC id → the map it stands on (the client's 추적 walks there; track.js)
    npcMap: { ...NPC_MAP },
    side: SIDE.map(sideDef),
    // the turning day and the weather (the client keeps the same clock), the fire's company
    sky: { dayMs: SKY_DAY_MS, phases: PHASES, weather: WEATHER, wxMs: WX_MS, warm: [WARM_N, WARM_BASE, WARM_STEP, WARM_NIGHT, WARM_REGEN], tales: TALES, teller: TELLER.name, jam: JAM, season: SEASON.name },
    fair: fairDefs(),
    // life skills: names, curve, grades, the bonus formula, fish, recipes, each map's grade (58-life.js)
    life: lifeDefs(), npclife: npcLifeDefs(),
    // charms: shapes, options and caps, legendaries, the expansion order and prices, 주아나's quests (66-charms.js)
    charms: charmDefs(),
    // 협동 아르바이트: the jobs, cut-offs, tools (68-coop.js)
    coop: coopDefs(),
    alba: albaDefs(),
    sx: sxDefs(),
    // boss trophies: { list: { kind: { name, fx } }, cap, p, gold, story: { r, limit } } (67-trophies.js)
    trophies: trophyDefs(),
    streak: [STREAK_MS, STREAK_MAX], guildCost: GUILD_COST, guildXp: GUILD_XP, fireR: FIRE_R, lookCost: LOOK_COST, lookMax: LOOK_MAX, emotes: EMOTES, dim: dimDefs(), maps: worldMapDefs(),
    // ITEM LEVEL (owner 2026-11-16). A gear entry on the wire carries `il` (shown 1–200 scale); the level it can be worn from is
    //   max(1, entry.il − ilGap)   (what validateAction "eq" checks; an entry without `il` = items[id].req + ilGap, or 1 for req 1)
    // Gear `rarity` uses 0, 1, 2, 3 and 5, with 5 retained as the existing unique code.
    // Legendary and unique gear use their `lg` power's name prefix. Runes have a separate grade table.
    ilGap: IL_GAP,
    // the 아이템도감 (public/dex.js): the keys of `legend` that are live (can drop); the other rows are listed there as 준비 중
    pfxOn: Object.keys(LEGEND).filter((k) => PFX[k] && PFX[k].on && !PFX[k].off),
  };
}
